  return (
    <div id="create-object-container"> 
      {/* Asset Selection & Creation */}
      <select id="asset-selector" value={value} onChange={(e) => {
        if (e.target.value) {
          model.createObject(e.target.value).then(() => { 
            model.setSelectedAsset(e.target.value); 
          });
        }
      }}>
        {model.availableAssets.map((asset, index) => (
          <option key={index} value={asset}>{asset}</option> 
        ))}
      </select>

      {/* Display Selected Asset (Potentially with enhanced ID for dynamic updates) */}
      <div id="selected-asset-preview">{model.selectedAsset && <>{model.selectedAsset}</>}</div>

      {/* Cleanup Button */}
      <button id="cleanup-scene-button" onClick={model.cleanupScene}>Cleanup scene</button>
    </div>
  )
})
