```javascript
function swapAdjectives(sentence) {
  const words = sentence.split(' ');
  let adjectivePos = -1; // Initialize to find the first adjective

  for (let i = 0; i < words.length; i++) {
    if (isAdjective(words[i])) {  // Use a helper function to identify adjectives (see below)
      adjectivePos = i;
      break; 
    }
  }

  if (adjectivePos !== -1) {
    // Swap positions
    [words[adjectivePos], words[adjectivePos - 1]] = [words[adjectivePos - 1], words[adjectivePos]];
    return words.join(' '); 
  } else {
    return sentence; // Handle cases with no clear adjective upfront
  }
}

// Helper function (expandable for more nuanced adjective detection)
function isAdjective(word) {
  // Simple rule: Check common adjective endings (adapt as needed for accuracy)
  return word.toLowerCase().endsWith('ful') || word.toLowerCase().endsWith('ous') || 
         word.toLowerCase().endsWith('ive') || ['red', 'blue', 'green', 'tall', 'small'].includes(word.toLowerCase()); 
}

// Example usage:
const sentence = "Beautiful green trees are in the park";
const reorderedSentence = swapAdjectives(sentence);
console.log(reorderedSentence); // Output: Green beautiful trees are in the park 
```

