const { WebClient } = require('@slack/client'); // Assuming you have the Slack API library installed

async function postToSlack(text, channelId, token) {
  // Initialize Slack WebClient with your bot token
  const web = new WebClient(token);

  // Construct the message payload for Slack API
  const message = {
    channel: channelId,  // Channel ID to post in
    text: text,           // The content to send
  };

  try {
    // Send the message using Slack API's chat.postMessage method
    const response = await web.chat.postMessage(message); 
    console.log(`Message posted successfully! Thread TS: ${response.ts}`); 
    return { success: true, threadTs: response.ts }; // Return success and thread timestamp for future reference
  } catch (error) {
    console.error(`Error posting to Slack: ${error.message}`);
    return { success: false, error: error.message }; 
  }
}

// **Usage Example:**
const mySlackToken = 'YOUR_SLACK_BOT_TOKEN';  // Replace with your actual bot token
const targetChannel = 'your_channel_id';    // Replace with the desired channel ID

postToSlack('This is a message sent via JavaScript!', targetChannel, mySlackToken)
  .then(result => {
    if (result.success) {
      console.log(`Message thread timestamp: ${result.threadTs}`);
      // Handle successful posting (e.g., update UI, log further details)
    } else {
      console.error(result.error); // Handle errors appropriately
    }
  });
```

