#include <iostream>
#include <limits>

using namespace std;

// Recursive Fibonacci function
int fibonacci(int a, int b, int n) {
    if (n == 0) return a;  // Base case: 0th element is the first input
    else if (n == 1) return b; // Base case: 1st element is the second input
    else return fibonacci(b, a + b, n - 1);
}

int main() {
    int start1, start2, count;

    // Input and Error Handling
    cout << "Enter the first two Fibonacci numbers: ";
    while (!(cin >> start1 >> start2)) {  // Ensure both inputs are numeric
        cin.clear();  // Clear error flags
        cin.ignore(numeric_limits<streamsize>::max(), '\n'); // Discard invalid input
        cerr << "Invalid input. Please enter integers.\n";
    }
    if (start1 < 0 || start2 < 0) {
        cerr << "Error: Both starting numbers must be non-negative.\n";
        return 1; // Indicate an error
    }

    cout << "Enter the desired number of elements: ";
    while (!(cin >> count) || count <= 0) {  // Validate count as positive integer
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
        cerr << "Invalid input. Please enter a positive integer.\n";
    }

    // Generate and Output Fibonacci Sequence
    cout << "Fibonacci Sequence (starting with " << start1 << ", " << start2 << "): ";
    for (int i = 0; i < count; ++i) {
        cout << fibonacci(start1, start2, i) << ", ";
        // Update start1 and start2 for the next iteration (implicit in recursive calls)
    }
    cout << endl; // Final newline for cleaner output

    return 0; 
}
```

